info.onCountdownEnd(function () {
    game.gameOver(true)
})
// Ball hits paddle
sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Player, function (ball, paddle) {
    ball.vy = 0 - Math.abs(ball.vy)
    info.changeScoreBy(1)
    music.play(music.melodyPlayable(music.baDing), music.PlaybackMode.InBackground)
})
// Ball touches the big line = GAME OVER
sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Enemy, function (ball, line) {
    game.over(false)
})
game.splash("Ping Pong")
info.startCountdown(15)
// Background
scene.setBackgroundColor(9)
info.setScore(0)
// Paddle
let paddle = sprites.create(img`
    . . . . . . . . . . . . . . . . . . . . . . . . 
    . . . . . . . . . . . . . . . . . . . . . . . . 
    2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 
    2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 
    2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 
    . . . . . . . . . . . . . . . . . . . . . . . . 
    . . . . . . . . . . . . . . . . . . . . . . . . 
    `, SpriteKind.Player)
paddle.setPosition(80, 105)
// Ball
let ball = sprites.create(img`
    . . 2 2 . . 
    . 2 2 2 2 . 
    2 2 2 2 2 2 
    2 2 2 2 2 2 
    . 2 2 2 2 . 
    . . 2 2 . . 
    `, SpriteKind.Projectile)
ball.setPosition(80, 50)
ball.setVelocity(70, 70)
ball.setBounceOnWall(true)
// BIG GAME-OVER LINE BELOW THE PADDLE
let gameOverLine = sprites.create(img`
    
    
    
    
    `, SpriteKind.Enemy)
gameOverLine.setPosition(80, 118)
// Move paddle with buttons
controller.moveSprite(paddle, 100, 0)
// Keep paddle inside screen
paddle.setStayInScreen(true)
